{"command": "/tmp/opensip-architecture-review-env/bin/python -I -B << 'PY'
import json
from pathlib import Path
base = Path("/tmp/opensip-design-corrections/consumer-b.v12-fresh-export-admission.v1")

# Peek one export store structure (keys, sizes, sample object)
p = base/"exports"/"syntax-data.store.json"  # smallest
# Don't load entire 500k if we can peek top keys with ijson... just load
store = json.loads(p.read_text())
print("top keys:", list(store.keys()) if isinstance(store, dict) else type(store))
if isinstance(store, dict):
    for k,v in store.items():
        if isinstance(v, dict):
            print(f"  {k}: dict n={len(v)} sample_keys={list(v.keys())[:8]}")
        elif isinstance(v, list):
            print(f"  {k}: list n={len(v)}")
            if v:
                print("    first type", type(v[0]).__name__, list(v[0].keys())[:12] if isinstance(v[0], dict) else str(v[0])[:80])
        else:
            print(f"  {k}: {type(v).__name__} {str(v)[:120]}")
PY
", "description": "Inspect export store JSON top-level structure"}

{"command": "/tmp/opensip-architecture-review-env/bin/python -I -B << 'PY'
import json
from pathlib import Path
from collections import defaultdict

p = Path("/tmp/opensip-design-corrections/consumer-b.v12-fresh-export-admission.v1/subject/docs/coop/design-corrections/foundation/identity-schemas.v3.json")
data = json.loads(p.read_text())

# Walk all x-opensip-digest and x-opensip-order annotations
annots = []

def walk(node, path):
    if isinstance(node, dict):
        if "x-opensip-digest" in node:
            annots.append(("digest", path, node["x-opensip-digest"]))
        if "x-opensip-order" in node:
            annots.append(("order", path, node["x-opensip-order"]))
        for k,v in node.items():
            walk(v, path + "/" + k)
    elif isinstance(node, list):
        for i,v in enumerate(node):
            walk(v, path + f"[{i}]")

walk(data, "")
print("digest annotations:", sum(1 for a in annots if a[0]=="digest"))
print("order annotations:", sum(1 for a in annots if a[0]=="order"))
print("\n=== ALL DIGEST ANNOTATIONS ===")
for kind, path, val in annots:
    if kind=="digest":
        print(path)
        print("   ", json.dumps(val)[:400])
print("\n=== ALL ORDER ANNOTATIONS ===")
for kind, path, val in annots:
    if kind=="order":
        print(path, "=>", json.dumps(val)[:200])
