                            "NON_SCALAR_UNICODE",
                            "lone surrogate \\u escape",
                            self.citation,
                            {"codepoint": hex(cp)},
                        )
                    out.append(chr(cp))
                    i += 6
                    continue
                mapping = {
                    '"': '"',
                    "\\": "\\",
                    "/": "/",
                    "b": "\b",
                    "f": "\f",
                    "n": "\n",
                    "r": "\r",
                    "t": "\t",
