import json, base64, struct
from pathlib import Path
base = Path("/tmp/opensip-design-corrections/consumer-b.v12-fresh-export-admission.v1")
PREFIX = b"opensip.product.v1\x00"

def parse_frame(raw):
    rest = raw[len(PREFIX):]
    z = rest.find(b"\x00")
    domain = rest[:z].decode()
    rest = rest[z+1:]
    payload = rest[8:]
    return domain, json.loads(payload)

store = json.loads((base/"exports"/"syntax-data.store.json").read_text())
# coverage payloads
for k,v in store["objectTable"].items():
    if not isinstance(v, dict):
        continue
    if v.get("kind")=="canonical-record" and str(v.get("label","")).startswith("cvp"):
        raw = base64.b64decode(store["blobs"][k if k in store["blobs"] else v["digest"]])
        rec = json.loads(raw)
        entry = rec.get("entry") or {}
        key = rec.get("key") or {}
        print(v.get("label"), "rel", key.get("relation"), "rung", key.get("resolution"), "coverage", entry.get("coverage"), "def", entry.get("deficiency"), "cause", entry.get("nativeCause"))

print("\n--- scopes ---")
for k,v in store["objectTable"].items():
    if isinstance(v, dict) and v.get("domain")=="subject-scope" and ":" not in k:
        raw = base64.b64decode(store["blobs"][v["digest"]])
        d, rec = parse_frame(raw)
        print(v.get("label"), rec.get("relation"), rec.get("resolution"), "subjects", rec.get("subjects"))
